def split_legacy_permissions(apps, schema_editor):
    """Überführt alte Sammelrechte in gleichwertige Einzelrechte und entfernt sie."""
    Permission = apps.get_model("auth", "Permission")
    ContentType = apps.get_model("contenttypes", "ContentType")
    QuestionPool = apps.get_model("core", "QuestionPool")
    database = schema_editor.connection.alias
    content_type, _ = ContentType.objects.using(database).get_or_create(
        app_label="core",
        model="questionpool",
    )

    for legacy_codename, destinations in GLOBAL_SPLITS.items():
        try:
            old = Permission.objects.using(database).get(
                content_type=content_type, codename=legacy_codename
            )
        except Permission.DoesNotExist:
            continue
        for codename, label in destinations:
            target, _ = Permission.objects.using(database).get_or_create(
                content_type=content_type,
                codename=codename,
                defaults={"name": label},
            )
            target.group_set.add(*old.group_set.using(database).all())
            target.user_set.add(*old.user_set.using(database).all())
        old.delete(using=database)

    for legacy_codename, (codename, label) in GLOBAL_COPIES.items():
        try:
            old = Permission.objects.using(database).get(
                content_type=content_type, codename=legacy_codename
            )
        except Permission.DoesNotExist:
            continue
        target, _ = Permission.objects.using(database).get_or_create(
            content_type=content_type,
            codename=codename,
            defaults={"name": label},
        )
        target.group_set.add(*old.group_set.using(database).all())
        target.user_set.add(*old.user_set.using(database).all())

    pools = QuestionPool.objects.using(database).all()
    for legacy_prefix, destinations in POOL_SPLITS.items():
        for pool in pools:
            legacy_codename = f"{legacy_prefix}{pool.pk}"
            try:
                old = Permission.objects.using(database).get(
                    content_type=content_type, codename=legacy_codename
                )
            except Permission.DoesNotExist:
                continue
            keep_legacy_record = False
            for new_prefix, label in destinations:
                new_codename = f"{new_prefix}{pool.pk}"
                if new_codename == legacy_codename:
                    target = old
                    keep_legacy_record = True
                else:
                    target, _ = Permission.objects.using(database).get_or_create(
                        content_type=content_type,
                        codename=new_codename,
                        defaults={"name": f"{label}: {pool.name}"},
                    )
                target.group_set.add(*old.group_set.using(database).all())
                target.user_set.add(*old.user_set.using(database).all())
            if not keep_legacy_record:
                old.delete(using=database)

    # Diese Rechte waren früher nur Schreib-/Anzeige-Gates ohne eigene Aktion;
    # sie werden entfernt, nicht als Ersatz für Einzelaktionen interpretiert.
    Permission.objects.using(database).filter(
        content_type=content_type,
        codename__in=("can_manage_users", "can_manage_tool_settings"),
    ).delete()


